#include<bits/stdc++.h>
using namespace std;int main(){const int T=3840,F=128,N=3968;vector<array<int8_t,16>> V(T);ifstream a("research/mixed_tier17_eval_subgroup_20261105/cache/mixed17_eval4_orbits.bin",ios::binary);a.read((char*)V.data(),T*16);vector<uint16_t> H(16);ifstream b("research/mixed_tier17_eval_subgroup_20261105/cache/mixed17_eval4_group.bin",ios::binary);b.read((char*)H.data(),32);vector<uint8_t>C(T*F),G(F*F);ifstream c("research/mixed_tier17_eval_subgroup_20261105/cache/mixed17_eval4_same.bin",ios::binary);c.read((char*)C.data(),C.size());ifstream d("research/mixed_tier17_eval_subgroup_20261105/cache/mixed17_eval4_flat_graph.bin",ios::binary);d.read((char*)G.data(),G.size());ofstream out("research/mixed_tier17_eval_subgroup_20261105/cache/graph_edges.bin",ios::binary);long long count=0;auto add=[&](int x,int y){out.write((char*)&x,4);out.write((char*)&y,4);count++;};for(int i=0;i<F;i++)for(int j=i+1;j<F;j++)if(G[F*i+j])add(i,j);for(int i=0;i<T;i++)for(int j=0;j<F;j++)if(C[F*i+j])add(j,F+i);for(int i=0;i<T;i++){for(int j=i+1;j<T;j++){bool conflict=false;for(int h:H){int dot=0;for(int k=0;k<16;k++)dot+=int(V[i][k])*int(V[j][k])*(((h>>k)&1)?-1:1);if(dot>8){conflict=true;break;}}if(conflict)add(F+i,F+j);}if(i%500==0)cerr<<"tier "<<i<<" edges "<<count<<"\n";}cout<<"vertices "<<N<<" edges "<<count<<"\n";}
